import * as React from 'react';
import * as MorphingTabsPrimitive from '@exhuma/core';
import { clsx } from 'clsx';

export interface MorphingTabsProps extends React.ComponentPropsWithoutRef<typeof MorphingTabsPrimitive.MorphingTabs> {
  className?: string;
}

export const MorphingTabs = React.forwardRef<HTMLDivElement, MorphingTabsProps>(
  ({ className, children, ...props }, ref) => (
    <MorphingTabsPrimitive.MorphingTabs
      ref={ref}
      className={clsx(
        'relative flex items-center gap-1 rounded-2xl border border-border bg-muted/40 p-1.5 shadow-sm',
        className
      )}
      {...props}
    >
      {children}
    </MorphingTabsPrimitive.MorphingTabs>
  )
);
MorphingTabs.displayName = 'MorphingTabs';

