import { Component, JSX, splitProps } from 'solid-js';
import * as MorphingTabsPrimitive from '@exhuma/core';

export interface MorphingTabsProps extends JSX.HTMLAttributes<HTMLDivElement> {
  [key: string]: unknown;
}

export const MorphingTabs: Component<MorphingTabsProps> = (props) => {
  const [local, others] = splitProps(props, ['class', 'children']);
  return (
    <MorphingTabsPrimitive.MorphingTabs
      class={`relative flex items-center gap-1 rounded-2xl border border-border bg-muted/40 p-1.5 shadow-sm ${local.class ?? ''}`}
      {...others}
    >
      {local.children}
    </MorphingTabsPrimitive.MorphingTabs>
  );
};

