import { MorphingTabs } from '@exhuma/core';

class ExhumaMorphingTabsElement extends HTMLElement {
  connectedCallback() {
    this.classList.add('exhuma-morphing-tabs');
    this.style.display = 'block';
  }
}

if (!customElements.get('exhuma-morphing-tabs')) {
  customElements.define('exhuma-morphing-tabs', ExhumaMorphingTabsElement);
}

